-- Closing Review v7: granular direct transaction exceptions.
-- Built only from v6 structural behavior; no human labels are used here.

update public.intelligence_model_versions
set scoring_notes = coalesce(scoring_notes,'') || ' STRUCTURAL RESULT 2026-08-19: 48/48 fresh scorable across 21 counties, but only 4 distinct scores and 7 unique feature vectors; v6 failed structural diversity and is frozen for audit. No human labels were used.'
where model_key='closing_review' and version=6;

on conflict (marker_id) do update set engine_version=excluded.engine_version,formula=excluded.formula,dependencies=excluded.dependencies,confidence=excluded.confidence,status=excluded.status,explanation=excluded.explanation,operation=excluded.operation,config=excluded.config,updated_at=excluded.updated_at;

on conflict (feature_key,version) do update set source_key=excluded.source_key,label=excluded.label,transform_type=excluded.transform_type,config=excluded.config,direction=excluded.direction,status=excluded.status,explanation=excluded.explanation;

jsonb_build_object('input_contract','closing_granular_actionable_exception_v7','requires_evidence',true,'minimum_evidence_coverage',100,'aggregation','max_direct_exception','signals',jsonb_build_array(
jsonb_build_object('id','watchdog.closing_actionable_exception_attention_v7','role','score','weight',1.0),
jsonb_build_object('id','watchdog.closing_permit_lifecycle_exception_v7','role','support'),
jsonb_build_object('id','watchdog.closing_recording_exception_v7','role','support'),
jsonb_build_object('id','watchdog.closing_permit_closure_gap_v7','role','support'),
jsonb_build_object('id','watchdog.closing_recording_reference_gap_v7','role','support'),
jsonb_build_object('id','watchdog.closing_actionable_evidence_coverage_v7','role','confidence')),
'supporting_context_policy',jsonb_build_object('environmental_flood_tidelands','context_only','may_independently_create_priority',false),
'holdout_policy',jsonb_build_object('development_sanity_review_first',true,'development_sanity_cases',10,'fresh_independent_labels_required',true,'reuse_v5_labels_as_promotion_proof',false,'reuse_v6_shadow_as_promotion_proof',false,'structural_diversity_gate_required',true,'minimum_positive_cases',5,'minimum_negative_cases',5,'minimum_unique_feature_vectors',8)),
'uncalibrated','DRAFT v7. Created from v6 structural collapse only; no human labels used. Must pass unseen statewide structural diversity before any development sanity queue is created.')
on conflict (model_key,version) do update set label=excluded.label,description=excluded.description,objective=excluded.objective,minimum_plan=excluded.minimum_plan,status=excluded.status,profession_scope=excluded.profession_scope,signal_config=excluded.signal_config,calibration_state=excluded.calibration_state,scoring_notes=excluded.scoring_notes;
